import {gardenContactHeight} from '../../../../src/js/garden/GardenContact.js';
import assert from 'node:assert/strict';
import {createGardenState,stepGarden,restoreGardenState,retryGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN as C,GARDEN_PLATFORMS,GARDEN_WHEELS,GARDEN_AERIAL,GARDEN_CHECKPOINTS,GARDEN_LEGACY_CHECKPOINTS,GARDEN_ENEMIES,GARDEN_TERRAINS,GARDEN_PLATFORM_BY_ID,GARDEN_WATERS,gardenPlatforms,gardenSurfaceY,cloudStatus,GARDEN_FINAL_START} from '../../../../src/js/garden/GardenLevel.js';
const advance=(s,input,seconds)=>{const events=[];for(let t=0;t<seconds-1e-9;t+=1/120)events.push(...stepGarden(s,input,Math.min(1/120,seconds-t)));return events;};
function on(id,difficulty='NORMAL'){const s=createGardenState(difficulty),p=GARDEN_PLATFORM_BY_ID.get(id);s.stage='RUNNING';Object.assign(s.player,{x:p.x+100,y:p.y,onGround:true,support:id,terrain:p.type});s.trail=[id];s.safeGround=p.ground?id:'entrada';return s;}
for(const [id,speed]of [['entrada',220],['primeira-grama',100],['pedrinhas-da-roda',410]]){
 const s=on(id);advance(s,{x:1},.5);assert.ok(Math.abs(s.player.vx-speed)<1,'Velocidade própria do material');const x=s.player.x;stepGarden(s,{x:0});assert.equal(s.player.x,x,'Soltar para, inclusive nas pedrinhas');assert.equal(s.player.vx,0);
 if(id!=='entrada')assert.ok(s.player.discomfort>.9,'Desconforto persistente no terreno');
}
const impulses=[];for(let i=0;i<4;i++){const s=on('pedrinhas-da-roda');s.jumps=i;stepGarden(s,{x:1,jump:true},1/120);impulses.push(s.player.vy);}assert.equal(new Set(impulses).size,4,'Pulos das pedrinhas variam de forma determinística');
for(const difficulty of ['NORMAL','EASY']){
 const s=createGardenState(difficulty);s.stage='RUNNING';s.player.x=GARDEN_WATERS[0].x+20;s.player.y=C.waterY+5;s.player.onGround=false;stepGarden(s,{});assert.equal(s.stage,difficulty==='EASY'?'RESCUING':'FALLING','Água fatal NORMAL/resgate EASY');
 if(difficulty==='EASY'){const restored=restoreGardenState(JSON.parse(JSON.stringify(s)),difficulty);advance(restored,{},2);assert.equal(restored.stage,'RUNNING');assert.equal(restored.player.support,'entrada');assert.equal(restored.hp,6);}
 const fall=createGardenState(difficulty);fall.stage='RUNNING';fall.player.x=720;fall.player.y=900;fall.player.onGround=false;stepGarden(fall,{});assert.equal(fall.stage,difficulty==='EASY'?'RESCUING':'FALLING','Buraco fatal NORMAL/resgate EASY');
}
const base=GARDEN_ENEMIES.find(e=>e.type==='caterpillar');const s=on('primeiros-bichinhos');let e=s.enemies.find(v=>v.id===base.id);
function stomp(){Object.assign(s.player,{x:e.x,y:e.y-e.h-3,vy:260,onGround:false,support:null,airSpeed:220});return advance(s,{x:0},.04);}
assert.ok(stomp().some(v=>v.type==='enrage'));assert.equal(e.hp,1);assert.ok(e.alive);const pos=e.x;advance(s,{x:0},.1);assert.ok(Math.abs(e.x-pos)>e.speed*.1*1.7,'Lagarta acelera após primeiro pisão');
advance(s,{},.25);stomp();assert.equal(e.hp,0);assert.equal(e.alive,false);assert.equal(s.defeated,1);
const ant=on('primeiros-bichinhos');e=ant.enemies.find(v=>v.type==='ant'&&!v.route);const y=e.y;Object.assign(ant.player,{x:e.x+200,y:590});let minY=y;for(let i=0;i<400;i++){stepGarden(ant,{},1/120);minY=Math.min(minY,e.y);}assert.ok(minY<y-20,'Formiga salta ao longo do ciclo');e.hopAge=1.4;
Object.assign(ant.player,{x:e.x,y:e.y-e.h-3,vy:300,onGround:false,support:null});advance(ant,{},.06);assert.equal(e.alive,false,'Formiga morre com um pisão');
const routeState=createGardenState(),routeAnt=routeState.enemies.find(v=>v.route);routeState.stage='RUNNING';routeState.immunity=4;Object.assign(routeState.player,{x:routeAnt.x+35,y:routeAnt.baseY,onGround:false,support:null});const oldX=routeAnt.x;advance(routeState,{},1.5);assert.notEqual(routeAnt.x,oldX,'Formiga avança para outra pedra');assert.ok(routeAnt.y<routeAnt.baseY,'Trajetória sobe entre pedras');
const cloud=GARDEN_PLATFORMS.find(p=>p.type==='cloud'),cloudState=createGardenState();cloudState.stage='RUNNING';Object.assign(cloudState.player,{x:cloud.x+50,y:cloud.y-12,vy:100,onGround:false});advance(cloudState,{},.15);assert.ok(cloud.id in cloudState.clouds,'Pouso arma a nuvem');const armed=cloudState.clouds[cloud.id];assert.ok(cloudStatus(cloud,cloudState,armed+2).solid);assert.ok(!cloudStatus(cloud,cloudState,armed+3).solid);assert.ok(!gardenPlatforms(armed+3,cloudState).some(p=>p.id===cloud.id),'Ausência também física');assert.ok(cloudStatus(cloud,cloudState,armed+7).solid,'Nuvem retorna');
assert.equal(GARDEN_PLATFORMS.filter(p=>p.group==='final').length,4);assert.ok(GARDEN_FINAL_START>C.width*.9,'Trecho misto domina a fase');
const hurt=on('primeiros-bichinhos','EASY');hurt.trail=['grama-da-margem','pedrinhas-da-roda','primeiros-bichinhos'];e=hurt.enemies.find(v=>v.type==='caterpillar');hurt.hp=1;Object.assign(hurt.player,{x:e.x,y:e.y});advance(hurt,{},.02);assert.equal(hurt.stage,'DISORIENTED');assert.equal(hurt.recovery.to.id,'grama-da-margem','Golpe fatal recua dois apoios');advance(hurt,{},2);assert.equal(hurt.stage,'RUNNING');assert.equal(hurt.hp,6);assert.ok(hurt.immunity>3);
const f=on('entrada');advance(f,{},8);assert.equal(f.fairy.mode,'guide');assert.ok(f.fairy.target);assert.ok(f.fairy.x>f.player.x+30,'Fada voa até o próximo apoio');
const saved=restoreGardenState(JSON.parse(JSON.stringify(hurt)),'EASY');assert.equal(saved.stage,'RUNNING');assert.deepEqual(saved.enemies,hurt.enemies);assert.equal(saved.difficulty,'EASY');
const invalid=JSON.parse(JSON.stringify(saved));invalid.clouds.entrada=4;assert.throws(()=>restoreGardenState(invalid,'EASY'));
const old={version:1,stage:'RUNNING',age:4,time:5,hp:3,checkpoint:120,player:{x:2000,y:590,vx:0,vy:0}};assert.equal(restoreGardenState(old).player.x,338,'Mapa antigo migra ao início seguro');
const dead=on('primeiros-bichinhos');dead.stage='GAME_OVER';dead.checkpoint=120;assert.ok(retryGarden(dead));assert.equal(dead.player.x,120);
console.log('APROVADO: terrenos/frenagem/pulos, fatalidade NORMAL, imortalidade/resgate/recuo EASY, lagarta de dois pisões, formiga saltadora e entre pedras, nuvens físicas/retorno, quatro nuvens finais, fada guia, save/restore/migração/retry.');

const disappearing=structuredClone(cloudState);advance(disappearing,{},6);assert.equal(disappearing.stage,'GAME_OVER','Menina não permanece suspensa quando a nuvem some');
const immortal=createGardenState('EASY');immortal.stage='RUNNING';for(let attempt=0;attempt<12;attempt++){Object.assign(immortal.player,{x:720,y:900,onGround:false});stepGarden(immortal,{});assert.equal(immortal.stage,'RESCUING');advance(immortal,{},2);assert.equal(immortal.stage,'RUNNING');assert.equal(immortal.hp,6);}
console.log('APROVADO: desaparecimento real sob os pés e doze resgates consecutivos sem GAME_OVER.');

const chase=on('primeiros-bichinhos');const hunter=chase.enemies.find(e=>e.type==='caterpillar'),home=GARDEN_PLATFORM_BY_ID.get(hunter.supportId);chase.immunity=99;hunter.x=home.x+400;
Object.assign(chase.player,{x:hunter.x,y:hunter.y-hunter.h-2,vy:300,onGround:false,support:null,facing:1});advance(chase,{},.02);
assert.equal(hunter.attackPhase,'retreat','Primeiro pisão inicia afastamento');const start=hunter.x;advance(chase,{},.35);assert.ok(hunter.x>start+70,'Sai debaixo da menina enquanto ela rebate no ar');assert.ok(hunter.alive&&hunter.hp===1,'Segundo pisão não é automático');
let phases=new Set();for(let i=0;i<150;i++){stepGarden(chase,{},1/120);phases.add(hunter.attackPhase);}
assert.ok(phases.has('windup')&&phases.has('charge'),'Recua, prepara e investe de frente');assert.deepEqual(restoreGardenState(JSON.parse(JSON.stringify(chase))).enemies,chase.enemies,'Save mantém reação e temporizadores');
advance(chase,{},8);assert.ok(hunter.x>=home.x+45&&hunter.x<=home.x+home.w-45,'Reposicionamento respeita o chão seguro');
console.log('APROVADO: lagarta se afasta do primeiro pisão, prepara investida frontal e conserva sua reação no save.');

// Cada subida é exercitada com a física de produção nos dois sentidos, sem inimigos na fixture.
let rises=0;
for(const a of GARDEN_PLATFORMS.filter(p=>p.ground))for(const b of GARDEN_PLATFORMS.filter(p=>p.ground&&Math.abs(p.x-a.x-a.w)<.01&&p.y<a.y)){
 assert.ok(a.y-b.y<=70,'Subida dentro da capacidade do salto');
 const state=on(a.id);state.enemies.forEach(e=>{e.alive=false;e.hp=0;});Object.assign(state.player,{x:a.x+a.w-C.halfFoot-45,y:a.y});advance(state,{x:1},1);assert.ok(state.player.x<=b.x-C.halfFoot+.1,'Parede impede andar para dentro da terra');
 let climbed=false;for(let t=0;t<120;t++){stepGarden(state,{x:1,jump:true},1/120);if(state.player.x>b.x&&state.player.y<=b.y+2)climbed=true;}assert.ok(climbed,'Salto sobe o patamar '+b.id+' '+JSON.stringify(state.player));rises++;
}
for(const b of GARDEN_PLATFORMS.filter(p=>p.ground))for(const a of GARDEN_PLATFORMS.filter(p=>p.ground&&Math.abs(p.x+p.w-b.x)<.01&&p.y<b.y)){
 const state=on(b.id);state.enemies.forEach(e=>{e.alive=false;e.hp=0;});Object.assign(state.player,{x:b.x+C.halfFoot+45,y:b.y});advance(state,{x:-1},1);assert.ok(state.player.x>=b.x+C.halfFoot-.1,'Face direita sólida');let climbed=false;for(let t=0;t<120;t++){stepGarden(state,{x:-1,jump:true},1/120);if(state.player.x<b.x&&state.player.y<=a.y+2)climbed=true;}assert.ok(climbed,'Salto sobe para a esquerda '+a.id);
}
for(const version of [2,3,4,5]){
 const [key,checkpoint]=[...GARDEN_LEGACY_CHECKPOINTS].filter(([key])=>key.startsWith(version+':'))[10];const legacy=structuredClone(createGardenState());legacy.version=version;legacy.stage='RUNNING';legacy.checkpoint=Number(key.split(':')[1]);legacy.player.x=legacy.checkpoint+700;legacy.enemies[0].alive=false;legacy.enemies[0].hp=0;
 const migrated=restoreGardenState(legacy);assert.equal(migrated.version,6);assert.equal(migrated.player.x,checkpoint);assert.equal(migrated.player.y,gardenContactHeight(GARDEN_PLATFORM_BY_ID.get(migrated.player.support),migrated.player));assert.equal(migrated.enemies[0].alive,false);assert.deepEqual(restoreGardenState(JSON.parse(JSON.stringify(migrated))),migrated);
}
console.log('APROVADO: '+rises+' subidas à direita, retorno à esquerda, paredes sólidas e migração v2/v3/v4 para checkpoint seguro no jardim v6 de cinco minutos.');

// Qualquer contato real dos sapatos sobre material opaco sustenta; transparência não sustenta.
for(const type of ['wood','stone','cloud']){const platform=gardenPlatforms(0).find(p=>!p.ground&&!p.rotating&&p.type===type);for(const side of [-1,1]){
 const state=createGardenState();state.stage='RUNNING';Object.assign(state.player,{x:side<0?platform.x-15:platform.x+platform.w+15,y:platform.y-30,vy:300,onGround:false,support:null});advance(state,{},.15);assert.equal(state.player.support,platform.id,'Ponta dos sapatos alcança '+type);
 const outside=createGardenState();outside.stage='RUNNING';Object.assign(outside.player,{x:side<0?platform.x-45:platform.x+platform.w+45,y:platform.y-30,vy:300,onGround:false,support:null});advance(outside,{},.15);assert.notEqual(outside.player.support,platform.id,'Sapatos inteiros fora de '+type);
}}
const wheel=gardenPlatforms(0).find(p=>p.rotating),rider=createGardenState();rider.stage='RUNNING';Object.assign(rider.player,{x:wheel.x+wheel.w/2,y:wheel.y,onGround:true,support:wheel.id});advance(rider,{},.5);const moved=gardenPlatforms(rider.time,rider).find(p=>p.id===wheel.id);assert.equal(rider.player.support,wheel.id);assert.ok(Math.abs(rider.player.y-gardenContactHeight(moved,rider.player))<.001);assert.ok(rider.player.x>moved.x&&rider.player.x<moved.x+moved.w);
console.log('APROVADO: contato parcial dos sapatos, exclusão da transparência e transporte pela roda.');

assert.equal(GARDEN_WHEELS.filter(w=>w.id.startsWith('aerea-')).length,3,'Três rodas no meio da fase');assert.ok(GARDEN_AERIAL.x>C.width*.3&&GARDEN_AERIAL.end<C.width*.7,'Travessia aérea no meio');assert.ok(!GARDEN_PLATFORMS.some(p=>p.ground&&p.x<GARDEN_AERIAL.end-360&&p.x+p.w>GARDEN_AERIAL.x+360),'Vão sem chão sob as rodas/nuvens/ilhas');assert.equal(GARDEN_PLATFORMS.filter(p=>p.aerial&&p.type==='gravel').length,2,'Duas ilhas rápidas no ar');
const aerialSave=createGardenState();aerialSave.stage='RUNNING';aerialSave.time=13;const support=gardenPlatforms(13,aerialSave).find(p=>p.wheelId==='aerea-2');Object.assign(aerialSave.player,{x:support.x+72,y:support.y,onGround:true,support:support.id});assert.equal(restoreGardenState(JSON.parse(JSON.stringify(aerialSave))).player.support,support.id,'Save na roda aérea');
const rescued=createGardenState('EASY');rescued.stage='RUNNING';rescued.safeGround='aereo-entrada';Object.assign(rescued.player,{x:GARDEN_AERIAL.x+2000,y:900,onGround:false});stepGarden(rescued,{});assert.equal(rescued.stage,'RESCUING');assert.equal(rescued.recovery.to.id,'aereo-entrada','Fada retorna à entrada firme, sem colocar sobre nuvem/ilha/roda');
console.log('APROVADO: três rodas, duas ilhas de pedrinhas, nuvens e vão aéreo sem chão; save em roda e resgate à entrada firme.');
const aerialDeath=createGardenState();aerialDeath.stage='GAME_OVER';aerialDeath.checkpoint=GARDEN_AERIAL.x+120;assert.ok(retryGarden(aerialDeath));assert.equal(aerialDeath.player.support,'aereo-entrada','Retry volta à entrada firme do setor aéreo');

// Regressão: descer rasante com apenas a ponta dos pés na quina não pode atravessar o morro.
let corners=0;
for(const wall of GARDEN_PLATFORMS.filter(p=>p.ground&&p.type!=='wood'))for(const direction of [-1,1])for(const frame of [1/120,1/60,.037])for(const distance of [3,11,13,17]){
 const state=createGardenState();state.stage='RUNNING';state.enemies.forEach(e=>{e.alive=false;e.hp=0;});
 Object.assign(state.player,{x:direction>0?wall.x-distance:wall.x+wall.w+distance,y:wall.y-.1,vy:240,vx:direction*220,airSpeed:220,onGround:false,support:null});
 const surfaces=GARDEN_PLATFORMS.filter(v=>v.ground).map(v=>gardenContactHeight(v,state.player)).filter(Number.isFinite);if(surfaces.length)state.player.y=Math.min(state.player.y,Math.min(...surfaces)-.1);
 for(let i=0;i<12;i++){
  stepGarden(state,{x:direction},frame);
  const p=state.player;
  for(const solid of GARDEN_PLATFORMS.filter(v=>v.ground&&p.x>v.x+.001&&p.x<v.x+v.w-.001))assert.ok(p.y<=solid.y+2,'Quina sólida '+wall.id+' '+direction+' '+distance+' '+JSON.stringify(p));
 }
 corners++;
}
console.log('APROVADO: '+corners+' descidas rasantes nas quinas, nos dois sentidos e em três cadências, sem entrar na terra.');

const hills=GARDEN_PLATFORMS.filter(p=>p.hill);assert.ok(hills.length>=5,'Morros arredondados variados');
for(const hill of hills)for(const dir of [-1,1]){
 const s=on(hill.id);s.enemies.forEach(e=>{e.alive=false;e.hp=0;});Object.assign(s.player,{x:dir>0?hill.x+20:hill.x+hill.w-20,y:gardenSurfaceY(hill,dir>0?hill.x+20:hill.x+hill.w-20)});
 for(let i=0;i<360&&s.player.x>hill.x&&s.player.x<hill.x+hill.w;i++){stepGarden(s,{x:dir},1/60);if(s.player.x<=hill.x||s.player.x>=hill.x+hill.w)break;assert.ok(s.player.onGround,'Caminhada acompanha curva sem cair');assert.ok(Math.abs(s.player.y-gardenContactHeight(GARDEN_PLATFORM_BY_ID.get(s.player.support),s.player))<.001,'Pés na curva real');}
 const snap=restoreGardenState(JSON.parse(JSON.stringify(s)));assert.deepEqual(snap.player,s.player,'Save no morro arredondado');
}
assert.ok(GARDEN_ENEMIES.length>35,'Mais inimigos apesar de fase menor');
console.log('APROVADO: '+hills.length+' morros arredondados, caminhada nos dois sentidos e save; mais inimigos em percurso menor.');

const falling=createGardenState();falling.stage='RUNNING';Object.assign(falling.player,{x:720,y:850,onGround:false});stepGarden(falling,{});assert.equal(falling.stage,'FALLING');const yBefore=falling.player.y;advance(falling,{},1);assert.equal(falling.stage,'FALLING');assert.ok(falling.player.y>yBefore,'Queda continua animada');advance(falling,{},1.5);assert.equal(falling.stage,'GAME_OVER');
const departure=createGardenState(),first=departure.player.x;advance(departure,{},1.5);assert.ok(departure.player.x>first&&departure.player.y>540,'Menina desce a escada');advance(departure,{},1.6);assert.equal(departure.stage,'RUNNING');assert.ok(Math.abs(departure.player.y-590)<.01);assert.equal(departure.player.x,530);
console.log('APROVADO: saída animada da casa, queda sem congelar e opções somente após Game Over.');
